 "A store holds {menus} menus.": "Un negozio contiene {menus} menu.",
 "A subdomain like mail.yourshop.com keeps this apart from your inbox.": "Un sottodominio come mail.yourshop.com lo tiene separato dalla tua casella di posta.",
