 "A visit is counted when the visitor leaves the page.": "Una visita viene contata quando il visitatore lascia la pagina.",
 "A visitor confirms their review from an email before it posts, and it is not marked Verified buyer or counted in your Storelib rating. A buyer who uses the form is sent their own link instead.": "Un visitatore conferma la recensione via email prima che venga pubblicata; non è segnata come Acquirente verificato né conta nella valutazione Storelib. A un acquirente che usa il modulo viene invece inviato il suo link.",
 "A visitor's details are sent only when their cookie choice allows it. Emails and phone numbers go hashed. Test sales are never sent.": "I dati di un visitatore vengono inviati solo se la sua scelta sui cookie lo consente. Email e numeri di telefono vanno con hash. Le vendite di test non vengono mai inviate.",
