 "An address with a password in it cannot be a link.": "Un indirizzo con una password non può essere un link.",
 "An email saying it's on the way.": "Un'email che dice che è in viaggio.",
 "An email to them bounced": "Un’email è stata respinta",
 "An email to them bounced or they marked one as spam, so nothing more is sent.": "Un’email è stata respinta o segnata come spam, quindi non si invia più nulla.",
 "An email with the tracking link.": "Un'email con il link di tracciamento.",
 "An email you start and do not send yet is kept here.": "Un'email iniziata e non ancora inviata resta qui.",
 "An empty React project.": "Un progetto React vuoto.",
 "An empty page with your header and footer": "Una pagina vuota con intestazione e piè di pagina",
 "An empty repository works best. If the branch is protected on GitHub, type a new one, such as storelib, and Storelib makes it.": "Un repository vuoto è la scelta migliore. Se il branch è protetto su GitHub, scrivine uno nuovo, come storelib, e Storelib lo crea.",
 "An error occurred": "Si è verificato un errore",
 "An error occurred while saving. Please try again.": "Si è verificato un errore durante il salvataggio. Riprova.",
 "An error occurred. Please try again.": "Si è verificato un errore. Riprova.",
 "An export from Judge.me, Yotpo, Loox, Stamped.io, Okendo, Reviews.io, Trustpilot, Google, Etsy, Amazon, WooCommerce, Fera, Ali Reviews or Rivyo, or any CSV or JSON file.": "Un'esportazione da Judge.me, Yotpo, Loox, Stamped.io, Okendo, Reviews.io, Trustpilot, Google, Etsy, Amazon, WooCommerce, Fera, Ali Reviews o Rivyo, o qualsiasi file CSV o JSON.",
 "An hour after a buyer leaves checkout without paying, if they asked for news.": "Un'ora dopo che un acquirente lascia il checkout senza pagare, se ha chiesto novità.",
 "An hour after a buyer leaves checkout without paying, if they asked for news. Turn it on in Checkout.": "Un'ora dopo che un acquirente lascia il checkout senza pagare, se ha chiesto novità. Attivalo in Checkout.",
 "An hour after someone presses Pay and no order comes of it. Only people who ticked “Email me news and offers” at checkout, or are on your list, get it, and it stops the moment they buy.": "Un'ora dopo che qualcuno preme Paga senza che nasca un ordine. La riceve solo chi ha spuntato “Inviami novità e offerte” al checkout o è nella tua lista, e si ferma appena acquista.",
 "An icon beside the title": "Un'icona accanto al titolo",
 "An image beside the title": "Un'immagine accanto al titolo",
 "An image or GIF": "Un'immagine o GIF",
 "An integration connects Storelib to a service you already use: Google Analytics, a pixel for your ads, a shipping or print on demand company.": "Un'integrazione collega Storelib a un servizio che usi già: Google Analytics, un pixel per gli annunci, un'azienda di spedizioni o di stampa su richiesta.",
 "An intro video": "Un video di presentazione",
 "An invite is already an approval, so this only applies to anyone who asks without one.": "Un invito è già un'approvazione, quindi vale solo per chi chiede senza invito.",
 "An invite lasts 1 to 365 days.": "Un invito dura da 1 a 365 giorni.",
 "An invite link is the only way in.": "Si entra solo con un link di invito.",
 "An mp4 or webm address": "Un indirizzo mp4 o webm",
 "An online shop for my hand-poured soy candles, with a warm and calm look, best sellers on the home page and the story of how they are made.": "Un negozio online per le mie candele di soia colate a mano, con un aspetto caldo e rilassante, i più venduti in home page e la storia di come vengono realizzate.",
 "An order": "Un ordine",
 "An order, a payout, a dispute, your website or something that isn't working. A real person at Storelib reads every one and replies here.": "Un ordine, un bonifico, una contestazione, il tuo sito o qualcosa che non funziona. Una persona vera di Storelib legge ogni richiesta e risponde qui.",
 "An unticked “Email me with news and offers” box under the email. Only buyers who tick it get your campaigns.": "Una casella non spuntata “Inviami novità e offerte” sotto l'email. Solo chi la spunta riceve le tue campagne.",
