 "Ask Storelib to step in": "Chiedi a Storelib di intervenire",
 "Ask Storelib writes it. Change it after.": "Ask Storelib la scrive. Modificala dopo.",
 "Ask a buyer how it is going, seven days after they bought.": "Chiedi a un acquirente come va, sette giorni dopo l'acquisto.",
 "Ask a few questions first": "Fai prima qualche domanda",
 "Ask about a product": "Chiedi di un prodotto",
 "Ask an order": "Chiedi a un ordine",
 "Ask an order for a review": "Chiedi una recensione per un ordine",
 "Ask buyers for a name, a message or a photo when they buy. You see their answers on the order.": "Chiedi agli acquirenti un nome, un messaggio o una foto quando comprano. Vedi le risposte nell'ordine.",
 "Ask for a change": "Chiedi una modifica",
 "Ask for a change, such as “make the hero taller”. It reads AGENTS.md first.": "Chiedi una modifica, come “rendi l'hero più alto”. Legge prima AGENTS.md.",
