 "Asked to join": "Ha chiesto di unirsi",
 "Asking buyers if they want to hear from you, the way the law in most places expects.": "Chiedere agli acquirenti se vogliono ricevere tue notizie, come richiede la legge nella maggior parte dei paesi.",
 "Asking for rates": "Richiesta tariffe in corso",
