 "Assign a file to {variantName}": "Assegna un file a {variantName}",
 "Assigned Files": "File assegnati",
 "Astrology": "Astrologia",
 "At": "Alle",
 "At a glance": "In breve",
 "At a time": "A un orario",
 "At checkout": "Al checkout",
 "At checkout Storelib adds the tax your settings above call for, shows it to the buyer, puts it on the receipt and keeps the record here. Nothing has to be set up before you can sell.": "Al checkout Storelib aggiunge l'imposta prevista dalle tue impostazioni qui sopra, la mostra all'acquirente, la riporta sulla ricevuta e ne conserva la registrazione qui. Non devi configurare nulla prima di vendere.",
 "At checkout Storelib adds the tax your settings below call for, shows it to the buyer, puts it on the receipt and keeps the record here. Nothing has to be set up before you can sell.": "Al checkout Storelib aggiunge l'imposta prevista dalle tue impostazioni qui sotto, la mostra all'acquirente, la riporta sulla ricevuta e ne conserva la registrazione qui. Non devi configurare nulla prima di vendere.",
 "At checkout Storelib looks at where the buyer is and adds that region's rate. Buyers anywhere else pay no tax.": "Al checkout Storelib guarda dove si trova l'acquirente e aggiunge l'aliquota di quella regione. Altrove non si pagano tasse.",
 "At checkout the buyer types their address. Storelib finds the zone it falls in and shows that zone's rates. An address in no zone cannot check out, so add every country you ship to.": "Al checkout l'acquirente inserisce l'indirizzo. Storelib trova la zona e ne mostra le tariffe. Un indirizzo fuori zona non può pagare, quindi aggiungi ogni paese in cui spedisci.",
 "At least 7 days. A card is taken at sign up and charged when the trial ends, unless they cancel.": "Almeno 7 giorni. La carta viene chiesta all'iscrizione e addebitata alla fine della prova, a meno che non annullino.",
 "At most {amount} can go back.": "Si possono restituire al massimo {amount}.",
 "At most {value}.": "Al massimo {value}.",
 "At or below it is low, for every product without its own line (set in the product's Inventory card).": "Pari o sotto è scarso, per ogni prodotto senza soglia propria (impostata nella scheda Inventario del prodotto).",
 "At the check": "Alla verifica",
 "At the end of the period": "Alla fine del periodo",
