 "Automatic": "Automatico",
 "Automatic link preview": "Anteprima automatica del link",
 "Automatic translation isn't set up on Storelib yet. You can still write each translation yourself.": "La traduzione automatica non è ancora configurata su Storelib. Puoi comunque scrivere ogni traduzione da te.",
 "Automatic translation keeps these words as written, or always uses your translation. Translations you write yourself are never changed.": "La traduzione automatica lascia queste parole come sono, o usa sempre la tua traduzione. Le traduzioni che scrivi tu non vengono mai cambiate.",
 "Automatic translation leaves product titles as you wrote them. You can still translate a title yourself on the product's Translations card.": "La traduzione automatica lascia i titoli dei prodotti come li hai scritti. Puoi comunque tradurre un titolo tu stesso nella scheda Traduzioni del prodotto.",
 "Automatic updates are not on yet": "Gli aggiornamenti automatici non sono ancora attivi",
