 "Changelog": "Novità",
 "Changes are saved as you make them and reach your checkout within a few seconds.": "Le modifiche si salvano mentre le fai e arrivano al checkout in pochi secondi.",
 "Changes go live when you save.": "Le modifiche vanno online quando salvi.",
 "Changes not published": "Modifiche non pubblicate",
 "Changes one of Storelib's sections in a way it can't use": "Modifica una sezione di Storelib in un modo che non può usare",
 "Changes one of {oneOfOurs} sections in a way it can't use": "Modifica una delle sezioni di {oneOfOurs} in un modo che non può usare",
 "Changes reach your live checkout within a few seconds. Nothing here touches orders already placed.": "Le modifiche arrivano al checkout online in pochi secondi. Nulla qui tocca gli ordini già effettuati.",
 "Changes saved": "Modifiche salvate",
 "Changes since published{value}": "Modifiche dalla pubblicazione{value}",
 "Changes to your account and its email address.": "Modifiche all'account e al suo indirizzo email.",
 "Changes to your store, checkout, taxes, shipping and integrations show up here.": "Le modifiche a negozio, checkout, tasse, spedizioni e integrazioni compaiono qui.",
 "Changing it signs you out on your other devices.": "Cambiandola esci dagli altri dispositivi.",
 "Changing the currency asks what happens to your prices: keep the numbers (100 EUR becomes 100 USD) or convert them at the day's exchange rate. Orders already placed keep their own currency.": "Cambiando valuta ti viene chiesto cosa succede ai prezzi: mantenere i numeri (100 EUR diventa 100 USD) o convertirli al cambio del giorno. Gli ordini già effettuati mantengono la loro valuta.",
 "Changing the words needs a database update (SQL part 129). The preview still works.": "Per cambiare il testo serve un aggiornamento del database (SQL parte 129). L'anteprima funziona comunque.",
 "Channel": "Canale",
 "Channels": "Canali",
 "Channels you create are for keeping track, like a market stall or a wholesale list. Storelib doesn't show anything there.": "I canali che crei servono a tenere traccia, come una bancarella o un listino all'ingrosso. Storelib non mostra nulla lì.",
 "Channels, messages, groups and chat rules": "Canali, messaggi, gruppi e regole della chat",
