 "Checkout": "Checkout",
 "Checkout always charges your store's own currency and says so next to the total, so a converted price is shown as an estimate.": "Il checkout addebita sempre nella valuta del tuo negozio e lo indica accanto al totale, quindi un prezzo convertito è una stima.",
 "Checkout canceled. Nothing changed.": "Checkout annullato. Non è cambiato nulla.",
 "Checkout charges the visitor's currency, the amounts they saw. A currency Storelib can't charge yet is shown for reference, and checkout says it charges yours.": "Il checkout addebita nella valuta del visitatore, gli importi che ha visto. Una valuta che Storelib non può ancora addebitare è mostrata come riferimento, e il checkout dice che addebita nella tua.",
 "Checkout charges what your store's prices are in, and says so next to the total, so a converted price is always shown as an estimate.": "Il checkout addebita nella valuta dei prezzi del negozio e lo indica accanto al totale, quindi un prezzo convertito è sempre una stima.",
 "Checkout conversion": "Conversione del checkout",
 "Checkout for the product they left": "Checkout del prodotto lasciato",
 "Checkout has no way to get an order to the buyer, so nobody can buy.": "Il checkout non ha modo di far arrivare l'ordine all'acquirente, quindi nessuno può comprare.",
 "Checkout is closed until payments are set up again, so buyers cannot pay you in the meantime.": "Il checkout resta chiuso finché non reimposti i pagamenti, quindi nel frattempo gli acquirenti non possono pagarti.",
 "Checkout is the page where a buyer types their details and pays. These settings decide what it asks for.": "Il checkout è la pagina in cui l'acquirente inserisce i dati e paga. Queste impostazioni decidono cosa chiede.",
 "Checkout link": "Link di checkout",
 "Checkout links": "Link di pagamento",
 "Checkout offer": "Offerta al checkout",
 "Checkout on {site}": "Checkout su {site}",
 "Checkout settings": "Impostazioni checkout",
 "Checkout settings need their database update (SQL part 109). Until it runs, checkout works as it always has and changes here are not kept.": "Le impostazioni del checkout richiedono l'aggiornamento del database (parte SQL 109). Fino ad allora il checkout funziona come sempre e le modifiche qui non vengono salvate.",
 "Checkout text": "Testi del checkout",
 "Checkout text needs its database update (SQL part 212). Until it runs, checkout shows Storelib's words and changes here are not kept.": "I testi del checkout richiedono l'aggiornamento del database (parte SQL 212). Fino ad allora il checkout mostra i testi di Storelib e le modifiche qui non vengono salvate.",
 "Checkout upsell": "Offerta al checkout",
