 "Downloads, courses and memberships. In the EU, VAT on digital sales is charged at the rate of the buyer's country, so add a region for each country you sell to.": "Download, corsi e abbonamenti. Nell'UE l'IVA sulle vendite digitali si applica con l'aliquota del paese dell'acquirente, quindi aggiungi una regione per ogni paese in cui vendi.",
