 "Drag the grip, or hold a card, to move it. With the keyboard, the up and down arrows move it one place.": "Trascina la maniglia, o tieni premuta una scheda, per spostarla. Da tastiera, le frecce su e giù la spostano di un posto.",
 "Drag the picture to choose what stays in view where it is cropped: the card beside your page, your card in Explore.": "Trascina l'immagine per scegliere cosa resta visibile dove viene ritagliata: la scheda accanto alla tua pagina, la tua scheda in Esplora.",
