 "GitHub won't let Storelib write to it. Send your site to a branch called storelib instead, and Storelib follows that one from now on.": "GitHub non permette a Storelib di scriverci. Invia il sito a un branch chiamato storelib, e da ora Storelib seguirà quello.",
 "GitHub's secret scanning would not take it. Everything else is on GitHub, and your site still uses the file. Send again after changing it.": "La scansione dei segreti di GitHub non l'ha accettato. Tutto il resto è su GitHub e il tuo sito usa ancora il file. Invia di nuovo dopo averlo modificato.",
 "Give a badge": "Assegna un badge",
