 "Imported reviews are marked Imported. They can show on your website, but they never get the Verified purchase label and never count in your Storelib rating.": "Le recensioni importate sono contrassegnate come Importate. Possono comparire sul tuo sito, ma non hanno mai l'etichetta Acquisto verificato e non contano mai nel tuo voto su Storelib.",
 "Imported theme": "Tema importato",
 "Imported themes show their own stars from the same ratings.": "I temi importati mostrano le proprie stelle con le stesse valutazioni.",
