 "Importing": "Importazione",
 "Importing {done} of {total}": "Importazione {done} di {total}",
 "Importing…": "Importazione…",
 "Improved loading skeleton structures for Explore, Analytics, and Upgrade pages to better match actual page layouts.": "Gli scheletri di caricamento di Esplora, Statistiche e Piani somigliano di più alle pagine vere.",
 "Improved settings page with smoother sticky save bar animations, toast notifications, and faster tab navigation with skeleton loading.": "Impostazioni con barra di salvataggio più fluida, notifiche e cambio scheda più veloce con caricamento progressivo.",
 "Improvement": "Miglioramento",
 "In 17TRACK, Settings > Webhook: add this address. 17TRACK signs updates with your API key. Without it Storelib checks every few hours.": "In 17TRACK, Settings > Webhook: aggiungi questo indirizzo. 17TRACK firma gli aggiornamenti con la tua chiave API. Senza, Storelib controlla ogni poche ore.",
 "In AfterShip, Settings > Webhooks: add this address, then paste its webhook secret under Change key, so updates arrive the moment they happen. Without it Storelib checks every few hours.": "In AfterShip, Settings > Webhooks: aggiungi questo indirizzo, poi incolla il segreto del webhook in Cambia chiave, così gli aggiornamenti arrivano subito. Senza, Storelib controlla ogni poche ore.",
 "In Brevo, open SMTP and API, API keys.": "In Brevo, apri SMTP e API, Chiavi API.",
 "In Flodesk, open Account settings, Integrations, API keys.": "In Flodesk, apri Impostazioni account, Integrazioni, Chiavi API.",
 "In Gelato, Developer › Webhooks, add this address for order status and tracking code updates:": "In Gelato, Developer › Webhooks, aggiungi questo indirizzo per stato degli ordini e codici di tracciamento:",
 "In Gelato, Developer › Webhooks, add this address for order status and tracking updates.": "In Gelato, Developer › Webhooks, aggiungi questo indirizzo per lo stato degli ordini e il tracciamento.",
 "In Google Ads, open Goals › Conversions › New conversion action › Import › Google Analytics 4 and pick them.": "In Google Ads, apri Obiettivi › Conversioni › Nuova azione di conversione › Importa › Google Analytics 4 e sceglili.",
 "In Google Analytics, Reports › Realtime shows a visit within a minute. The “Data collection isn't active” notice on your stream can take up to 48 hours to go away.": "In Google Analytics, Report › In tempo reale mostra una visita entro un minuto. L'avviso “La raccolta dei dati non è attiva” sul tuo stream può impiegare fino a 48 ore a sparire.",
 "In Google Analytics, open Admin › Product links › Google Ads links and link your Ads account.": "In Google Analytics, apri Amministrazione › Collegamenti ai prodotti › Collegamenti a Google Ads e collega il tuo account Ads.",
 "In Gumroad, open Settings › Advanced.": "In Gumroad, apri Settings › Advanced.",
 "In Kit, open Settings, Developer.": "In Kit, apri Impostazioni, Sviluppatore.",
 "In Mailchimp, open Profile, Extras, API keys.": "In Mailchimp, apri Profilo, Extra, Chiavi API.",
