 "Item weight from": "Peso dell'articolo da",
 "Items": "Articoli",
 "Items a print partner or supplier sends stay out of ShipStation. Print labels there as usual; the buyer gets the shipping email from your store.": "Gli articoli spediti da un partner di stampa o fornitore restano fuori da ShipStation. Stampa lì le etichette come sempre; l'acquirente riceve l'email di spedizione dal tuo negozio.",
 "Items from": "Articoli da",
 "Items fulfilled": "Articoli evasi",
 "Items marked shipped": "Articoli segnati come spediti",
 "Items returned": "Articoli resi",
 "Items up to": "Articoli fino a",
 "Its address": "Il suo indirizzo",
 "Its address, once published": "Il suo indirizzo, una volta pubblicata",
 "Its answers and any files sent with it are deleted. The person stays in your contacts if they are there for anything else.": "Le risposte e i file inviati con essa vengono eliminati. La persona resta nei tuoi contatti se c'è per altro.",
 "Its columns and sizes, with the numbers left for you.": "Le sue colonne e taglie, con i numeri da inserire tu.",
 "Its files and links go with it. This cannot be undone.": "I suoi file e link vanno via con lui. Non si può annullare.",
 "Its full page": "La sua pagina completa",
 "Its items aren't marked shipped. Ship them with it, or void it to get the money back.": "Gli articoli non sono segnati come spediti. Spediscili con essa o annullala per riavere il denaro.",
 "Its link works wherever it's listed. ": "Il suo link funziona ovunque sia elencato. ",
 "Its modules, lessons and their files are deleted. This cannot be undone.": "Moduli, lezioni e file vengono eliminati. Non si può annullare.",
 "Its name and cover are the course's own.": "Nome e copertina sono quelli del corso.",
 "Its options did not save. Add them in the editor.": "Le sue opzioni non sono state salvate. Aggiungile nell'editor.",
 "Its own height": "Altezza originale",
 "Its own shape": "La sua forma",
 "Its page is on your website, and menus and sections can show it.": "La sua pagina è sul tuo sito, e menu e sezioni possono mostrarla.",
 "Its page, posts, spaces, events, library, courses, chat and notifications go for everyone. {n, plural, one {# member loses} other {# members lose}} access. Orders and payments are kept.": "Pagina, post, spazi, eventi, libreria, corsi, chat e notifiche spariscono per tutti. {n, plural, one {# membro perde} other {# membri perdono}} l’accesso. Ordini e pagamenti restano.",
 "Its pages, settings and code are deleted. Export first to keep a copy.": "Pagine, impostazioni e codice vengono eliminati. Esporta prima per tenerne una copia.",
 "Its photos, price, variants and how many you have.": "Foto, prezzo, varianti e quanti ne hai.",
 "Its product is no longer in your store. Take it out of the library.": "Il suo prodotto non è più nel tuo negozio. Toglilo dalla libreria.",
 "Its size and weight make shipping by weight and labels right.": "Dimensioni e peso rendono corretti spedizioni a peso ed etichette.",
 "Its steps and history go with it.": "I suoi passaggi e la cronologia se ne vanno con lei.",
 "Its stock goes back on sale. The payment isn't refunded by this: use Refund on the order for that.": "La merce torna in vendita. Il pagamento non viene rimborsato: usa Rimborsa nell'ordine.",
 "Its style is in Design, under Layout.": "Lo stile è in Design, sotto Layout.",
 "Its video and files go too, and buyers lose the lesson.": "Il video e i file vengono eliminati e gli acquirenti perdono la lezione.",
 "Its weight is added to every parcel, so rates by weight come out right.": "Il suo peso si aggiunge a ogni pacco, così le tariffe a peso sono corrette.",
 "Its words and colours are set in Theme settings.": "Testi e colori si impostano in Impostazioni del tema.",
 "Its words, its style and a short line under it.": "Il testo, lo stile e una breve riga sotto.",
 "Its {length, plural, one {# lesson} other {# lessons}}, their videos and files go too, and buyers lose them.": "{length, plural, one {La sua # lezione} other {Le sue # lezioni}}, i video e i file vengono eliminati e gli acquirenti li perdono.",
