 "Of the emails sent in this period, how many had a link clicked.": "Delle email inviate in questo periodo, in quante è stato cliccato un link.",
 "Of the emails sent in this period, how many were opened.": "Delle email inviate in questo periodo, quante sono state aperte.",
 "Of the emails your automations sent, how many were opened. Some mail apps hide opens, so this is a floor.": "Delle email inviate dalle tue automazioni, quante sono state aperte. Alcune app nascondono le aperture, quindi è un minimo.",
 "Of the people who visited, how many opened a product, added it to the cart or pressed Buy, started a checkout, and how many orders came in. Each step is a share of the one before; the step that loses the most people is marked in red.": "Delle persone che hanno visitato, quante hanno aperto un prodotto, l'hanno aggiunto al carrello o premuto Acquista, hanno iniziato il checkout, e quanti ordini sono arrivati. Ogni passaggio è una quota del precedente; quello che perde più persone è in rosso.",
 "Of the people who visited, how many opened a product, how many started a checkout, and how many orders came in. Each step is shown as a share of the one before.": "Tra chi ha visitato, quanti hanno aperto un prodotto, quanti hanno avviato un checkout e quanti ordini sono arrivati. Ogni passaggio è mostrato come quota del precedente.",
 "Of this period's physical orders, the share that has been shipped or delivered, and how long a parcel waited from payment to shipped.": "Degli ordini fisici di questo periodo, la quota spedita o consegnata, e quanto ha atteso un pacco dal pagamento alla spedizione.",
