 "On. New people start it from now.": "Attiva. Le nuove persone iniziano da ora.",
 "Onboarding reminders": "Promemoria iniziali",
 "Once": "Una volta",
 "Once it has passed, say": "Una volta passato, mostra",
 "Once it is available you can cash it out, and it usually reaches your bank in 1 to 3 business days.": "Quando è disponibile puoi prelevarla, e di solito arriva in banca in 1-3 giorni lavorativi.",
 "Once it starts it cannot be taken back. You can stop the ones not yet sent.": "Una volta avviato non si può annullare. Puoi fermare quelle non ancora inviate.",
 "Once per person": "Una volta per persona",
 "Once saved, they'll appear on your OnePage.": "Una volta salvate, compariranno sulla tua OnePage.",
 "Once the items are back, mark them received: you choose whether they go back into stock, and you refund the buyer from the same screen.": "Quando gli articoli tornano, segnali come ricevuti: scegli se rimetterli in magazzino e rimborsi l'acquirente dalla stessa schermata.",
 "Once, now or at a time": "Una volta, ora o a un orario",
 "One": "Uno",
 "One a line, for example\nfree followers\ncrypto signal*": "Una per riga, ad esempio\nfollower gratis\nsegnale crypto*",
 "One a person a day": "Una a persona al giorno",
 "One article layout for every post: the cover, the author, related posts.": "Un unico layout per tutti gli articoli: la copertina, l'autore, gli articoli correlati.",
 "One at a time": "Una alla volta",
 "One choice": "Una scelta",
 "One colour": "Un solo colore",
 "One email a day at most, listing what sold down to its low stock line.": "Al massimo un'email al giorno, con ciò che è sceso alla soglia.",
 "One email a day per community, so your members keep reading them.": "Un'email al giorno per community, così i tuoi membri continuano a leggerle.",
 "One email an hour later with a link back to what they chose, only to buyers who ticked the news box. It stops the moment they buy.": "Un'email un'ora dopo con un link a ciò che avevano scelto, solo a chi ha spuntato la newsletter. Si ferma appena acquistano.",
 "One email an hour later, only to buyers who ticked the news box. With the news box hidden nobody can tick it, so no reminder goes out.": "Un'email un'ora dopo, solo a chi ha spuntato la newsletter. Con la casella nascosta nessuno può spuntarla, quindi non parte nessun promemoria.",
 "One email listing every parcel and its tracking link.": "Un'email con ogni pacco e il suo link di tracciamento.",
 "One email per order listing its parcels and tracking links.": "Un'email per ordine con i suoi pacchi e link di tracciamento.",
 "One email per order with its tracking link, or saying it's on the way.": "Un'email per ordine con il suo link di tracciamento, o per dire che è in viaggio.",
 "One emoji, or up to two letters.": "Un'emoji, o al massimo due lettere.",
 "One event has a price, and nobody can buy a ticket until payouts are connected.": "Un evento ha un prezzo e nessuno può comprare un biglietto finché non colleghi i bonifici.",
 "One event has a ticket price, but payouts are not connected, so nobody can buy it.": "Un evento ha un prezzo, ma i bonifici non sono collegati, quindi nessuno può comprarlo.",
 "One every {value}": "Uno ogni {value}",
 "One fewer": "Uno in meno",
 "One field": "Un campo",
