 "One file, a section per report": "Un file, una sezione per report",
 "One image at a time": "Un'immagine alla volta",
 "One kind of section: start the rule with": "Un tipo di sezione: inizia la regola con",
 "One kind of section: start the rule with {selector}. Your own coded sections keep their own styles unless you target them.": "Un tipo di sezione: inizia la regola con {selector}. Le tue sezioni scritte a codice mantengono i loro stili, a meno che tu non le selezioni.",
 "One less": "Uno in meno",
 "One line on cards and in Explore": "Una riga sulle schede e in Esplora",
 "One line under the name, on cards and in Explore.": "Una riga sotto il nome, sulle schede e in Esplora.",
