 "Online": "Online",
 "Online Tutoring": "Ripetizioni online",
 "Online course": "Corso online",
 "Online store": "Negozio online",
 "Only Storelib sees this.": "Solo Storelib lo vede.",
 "Only YouTube and Vimeo links can be added as a video.": "Solo i link di YouTube e Vimeo possono essere aggiunti come video.",
 "Only a community anyone can join is shown. Change that under Access and prices.": "Viene mostrata solo una community a cui chiunque può unirsi. Cambialo in Accesso e prezzi.",
 "Only approved translations show, and only once a language is published. Anything not translated yet shows in your default language, never blank.": "Compaiono solo le traduzioni approvate, e solo quando la lingua è pubblicata. Ciò che non è tradotto appare nella lingua predefinita, mai vuoto.",
 "Only buyers in {country} can order. You can add more places later.": "Solo gli acquirenti in {country} possono ordinare. Puoi aggiungere altri luoghi dopo.",
 "Only buyers who asked for your news": "Solo acquirenti che hanno chiesto le tue notizie",
 "Only changes the builder. In another language, the sidebar edits that language's text.": "Cambia solo l’editor. In un’altra lingua, la barra laterale modifica il testo di quella lingua.",
 "Only changes what you see here. Visitors choose their own.": "Cambia solo ciò che vedi qui. I visitatori scelgono le loro.",
 "Only for collections": "Solo per collezioni",
 "Only for me": "Solo per me",
 "Only if {phrase}": "Solo se {phrase}",
 "Only its author can add files and videos to this post.": "Solo chi ha scritto il post può aggiungere file e video.",
 "Only links and images go in a group.": "In un gruppo vanno solo link e immagini.",
 "Only members ever see Learn. This decides which of them can open the lessons.": "Solo i membri vedono Impara. Questo decide chi di loro può aprire le lezioni.",
 "Only members ever see Learn. This decides which of them open the lessons.": "Solo i membri vedono Impara. Questo decide chi di loro apre le lezioni.",
 "Only members ever see the Library. This decides which of them open it.": "Solo i membri vedono la Libreria. Qui decidi chi di loro lo apre.",
 "Only members on the tiers you pick.": "Solo i membri dei livelli che scegli.",
 "Only on orders over": "Solo per ordini oltre",
 "Only on orders over an amount": "Solo su ordini sopra un importo",
 "Only on this product so far.": "Per ora solo su questo prodotto.",
 "Only one currency can be for all other countries.": "Solo una valuta può essere per tutti gli altri paesi.",
 "Only orders delivered to these countries. Pickups can always pay in cash.": "Solo ordini consegnati in questi paesi. I ritiri si possono sempre pagare in contanti.",
 "Only orders placed after you turn the app on are asked. Buyers who turned review emails off, or already reviewed, are never asked.": "Vengono contattati solo gli ordini fatti dopo l'attivazione dell'app. Chi ha disattivato le email di recensione o ha già recensito non viene mai contattato.",
 "Only people subscribed to your emails get it.": "Lo ricevono solo gli iscritti alle tue email.",
 "Only people who asked for your news get it.": "La riceve solo chi ha chiesto le tue notizie.",
 "Only people who trigger it after you turn it on are sent anything. Someone who unsubscribes is never sent another email, wherever they are in the flow.": "Ricevono qualcosa solo quelli che la attivano dopo che l'hai accesa. Chi si disiscrive non riceve più email, ovunque sia nel flusso.",
 "Only people you invite": "Solo chi inviti",
 "Only photos and MP4, WebM or MOV videos.": "Solo foto e video MP4, WebM o MOV.",
 "Only some states or provinces": "Solo alcuni stati o province",
 "Only the email addresses were imported. Names and tags are kept once setup finishes.": "Sono stati importati solo gli indirizzi email. Nomi e tag verranno salvati al termine della configurazione.",
 "Only the first 2,000 rows are read. Import the rest as another file.": "Vengono lette solo le prime 2.000 righe. Importa il resto in un altro file.",
 "Only the first 5,000 rows were read. Import the rest in another file.": "Sono state lette solo le prime 5.000 righe. Importa il resto in un altro file.",
 "Only the first {count} option combinations come in.": "Vengono importate solo le prime {count} combinazioni di opzioni.",
 "Only the first {n} rows are read. Import the rest as a second file.": "Vengono lette solo le prime {n} righe. Importa il resto in un secondo file.",
 "Only the members you pick. Nobody else sees it.": "Solo i membri che scegli. Nessun altro lo vede.",
 "Only the owner can give this": "Solo il proprietario può concederlo",
 "Only the products below use these rates.": "Solo i prodotti qui sotto usano queste tariffe.",
 "Only the team sees it.": "Lo vede solo il team.",
 "Only the team starts conversations. Members can answer them.": "Solo il team avvia conversazioni. I membri possono rispondere.",
 "Only these products": "Solo questi prodotti",
 "Only to buyers who have not reviewed yet.": "Solo agli acquirenti che non hanno ancora recensito.",
 "Only to people who asked for your news": "Solo a chi ha chiesto le tue notizie",
 "Only verified buyers count toward your Storelib rating and get the Verified purchase label. Imported and visitor reviews can show on your website, but never count there.": "Solo gli acquirenti verificati contano nel tuo voto su Storelib e ricevono l'etichetta Acquisto verificato. Le recensioni importate e dei visitatori possono comparire sul tuo sito, ma lì non contano mai.",
 "Only web addresses (https://) can be links.": "Solo gli indirizzi web (https://) possono essere link.",
 "Only what Stripe needs to verify you in your country. It goes straight to Stripe and Storelib never keeps it.": "Solo ciò che serve a Stripe per verificarti nel tuo paese. Va direttamente a Stripe e Storelib non lo conserva mai.",
 "Only when this post first appeared on another website. Left empty, it is this post's own address.": "Solo se l'articolo è apparso prima su un altro sito. Se lo lasci vuoto, è l'indirizzo dell'articolo stesso.",
