 "Optional, like usps_priority (Shippo) or Priority (EasyPost). Empty: the cheapest.": "Facoltativo, come usps_priority (Shippo) o Priority (EasyPost). Vuoto: il più economico.",
 "Optional, the carrier's page for this parcel": "Facoltativo, la pagina del corriere per questo pacco",
 "Optional. A line under the name, for you.": "Facoltativo. Una riga sotto il nome, per te.",
 "Optional. Drag to reorder images.": "Facoltativo. Trascina per riordinare le immagini.",
 "Optional. Each paid order for this product is emailed here with the items and address. Empty: you pass orders on yourself.": "Facoltativo. Ogni ordine pagato di questo prodotto viene inviato qui via email con articoli e indirizzo. Vuoto: inoltri tu gli ordini.",
 "Optional. Empty: always free.": "Facoltativo. Vuoto: sempre gratis.",
 "Optional. How to measure, or how it fits.": "Facoltativo. Come misurare o come veste.",
 "Optional. Labels and return emails use it.": "Facoltativo. Lo usano le etichette e le email di reso.",
 "Optional. Leave it empty to always charge.": "Facoltativo. Lascia vuoto per addebitare sempre.",
 "Optional. Listed countries see and pay in their currency. Everyone else sees {currency}.": "Facoltativo. I paesi elencati vedono e pagano nella loro valuta. Tutti gli altri vedono {currency}.",
 "Optional. Put {tracking} where the number goes.": "Facoltativo. Metti {tracking} dove va il numero.",
 "Optional. The code after # on the order.": "Facoltativo. Il codice dopo # sull'ordine.",
 "Optional. Visitors from other countries see prices converted to their currency. Checkout always charges {currency}.": "Facoltativo. I visitatori di altri paesi vedono i prezzi convertiti nella loro valuta. Il checkout addebita sempre in {currency}.",
 "Optional. Visitors from other countries see your prices in their currency and pay in it.": "Facoltativo. I visitatori di altri paesi vedono i tuoi prezzi nella loro valuta e pagano in essa.",
 "Optional. Visitors in the countries you list see prices in that currency and pay in it. Everyone else sees {currency}. Anyone can switch with your website's currency selector.": "Facoltativo. I visitatori dei paesi che indichi vedono i prezzi in quella valuta e pagano in quella valuta. Tutti gli altri vedono {currency}. Chiunque può cambiare con il selettore di valuta del tuo sito.",
 "Optional. Visitors in these countries see your prices in their currency, can switch with your website's currency selector, and pay in it.": "Facoltativo. I visitatori di questi paesi vedono i prezzi nella loro valuta, possono cambiarla con il selettore di valuta del tuo sito e pagano in quella.",
