 "Strikethrough": "Barrato",
 "Stripe": "Stripe",
 "Stripe Connect": "Stripe Connect",
 "Stripe Connected Account Agreement": "Contratto per account connessi di Stripe",
 "Stripe Dashboard": "Dashboard di Stripe",
 "Stripe asks for these four digits to confirm who you are.": "Stripe chiede queste quattro cifre per confermare chi sei.",
 "Stripe checks your ID to confirm you are who you say you are. It goes straight to Stripe, and Storelib never sees or keeps the document.": "Stripe controlla il documento per confermare che sei proprio tu. Va direttamente a Stripe e Storelib non vede né conserva mai il documento.",
 "Stripe didn't answer just now, so this is your plan as of its last update. Nothing about it has changed.": "Stripe non ha risposto poco fa, quindi vedi il tuo piano com'era all'ultimo aggiornamento. Non è cambiato nulla.",
 "Stripe has your ID.": "Stripe ha ricevuto il documento.",
