 "Stripe is checking your ID. You can close this and go back to Storelib; we will tell you the moment it is done.": "Stripe sta controllando il documento. Puoi chiudere e tornare su Storelib; ti avviseremo appena finito.",
 "Stripe is saving the photo. If it doesn't answer, take it again.": "Stripe sta salvando la foto. Se non risponde, scattala di nuovo.",
 "Stripe is taking a closer look at this one. Nothing more is needed from you, and we'll email you the moment payments are on.": "Stripe sta esaminando con più attenzione. Non devi fare altro: ti scriveremo appena i pagamenti saranno attivi.",
