 "The Morning Writers": "Gli Scrittori del Mattino",
 "The Storelib app was removed from your GitHub account. Reconnect GitHub to keep syncing.": "L'app Storelib è stata rimossa dal tuo account GitHub. Ricollega GitHub per continuare la sincronizzazione.",
 "The account your payouts go to.": "Il conto su cui arrivano i bonifici.",
 "The activity log needs SQL part 113 (supabase/sql/run-now/113_store_activity.sql). Once it has run, changes show here from then on.": "Il registro attività richiede la parte SQL 113 (supabase/sql/run-now/113_store_activity.sql). Dopo l'esecuzione, le modifiche compariranno qui da quel momento.",
 "The address of your Storelib page": "L'indirizzo della tua pagina Storelib",
 "The address of your creator page and your OnePage": "L'indirizzo della tua pagina creator e della tua OnePage",
 "The answer": "La risposta",
 "The apron in Sage sold out.": "Il grembiule Salvia è esaurito.",
 "The apron was worn, so we can't take it back.": "Il grembiule è stato indossato, quindi non possiamo riprenderlo.",
 "The bank decided for you. The money was returned to your balance.": "La banca ha deciso a tuo favore. Il denaro è tornato nel tuo saldo.",
 "The bio and small print": "La bio e le note in piccolo",
 "The booking did not change. Try again.": "La prenotazione non è cambiata. Riprova.",
 "The boxes and mailers you ship in. The default one's weight is added to the order for weight based rates.": "Le scatole e le buste con cui spedisci. Il peso di quella predefinita si somma all'ordine per le tariffe a peso.",
 "The bread baking course": "Il corso di panificazione",
 "The business could not be created. Try again.": "Impossibile creare l'attività. Riprova.",
 "The button and the note on why it came stay the same.": "Il pulsante e la nota sul perché è arrivata restano uguali.",
 "The buyer": "L'acquirente",
 "The buyer asked for it": "L'ha chiesto l'acquirente",
 "The buyer asked for the receipt again": "L'acquirente ha richiesto di nuovo la ricevuta",
 "The buyer bought my preset pack on Oct 3, got the download email and downloaded the files twice the same day.": "L'acquirente ha comprato il mio pacchetto di preset il 3 ott., ha ricevuto l'email di download e ha scaricato i file due volte lo stesso giorno.",
 "The buyer can follow it at": "L'acquirente può seguirlo su",
 "The buyer can now ask Storelib to step in. Answer here to keep it between you.": "Ora l'acquirente può chiedere a Storelib di intervenire. Rispondi qui per risolvere tra di voi.",
 "The buyer changed their email": "L'acquirente ha cambiato la sua email",
 "The buyer chooses Cash on delivery at checkout. The order is placed at once, with no card, and you send it as usual.": "L'acquirente sceglie Pagamento alla consegna al checkout. L'ordine viene effettuato subito, senza carta, e lo spedisci come al solito.",
 "The buyer disputed this payment": "L'acquirente ha contestato questo pagamento",
 "The buyer does not recognise the payment on their statement.": "L'acquirente non riconosce il pagamento sull'estratto conto.",
 "The buyer drops it off": "L'acquirente lo consegna di persona",
 "The buyer follows it on {site}.": "L'acquirente lo segue su {site}.",
 "The buyer gets an email at each step: approved (with where to send it), received, and refunded.": "L'acquirente riceve un'email a ogni passaggio: approvato (con dove spedire), ricevuto e rimborsato.",
 "The buyer gets the money back on their original payment method.": "L'acquirente riceve il rimborso sul metodo di pagamento originale.",
 "The buyer paid at checkout.": "L'acquirente ha pagato al checkout.",
 "The buyer says they did not get what they paid for.": "L'acquirente dice di non aver ricevuto ciò che ha pagato.",
 "The buyer ships it back": "L'acquirente lo rispedisce",
 "The buyer's library": "La libreria dell'acquirente",
 "The carrier couldn't be read last time: {error} Storelib tries again.": "L'ultima volta non è stato possibile leggere il corriere: {error} Storelib riprova.",
 "The carrier reported a problem delivering this package. The buyer sees it and gets the Delivery problem email. Contact them or the carrier, then mark it in transit or delivered when it moves.": "Il corriere ha segnalato un problema nella consegna di questo pacco. L'acquirente lo vede e riceve l'email Problema di consegna. Contatta lui o il corriere, poi segnalo in transito o consegnato quando si muove.",
