 "The course could not be added. Try again.": "Impossibile aggiungere il corso. Riprova.",
 "The cover across the top of your page, then the gallery under it, in this order.": "La copertina in cima alla tua pagina, poi la galleria sotto, in questo ordine.",
 "The cover, then pictures and videos at the top of your page, the first one shown first.": "La copertina, poi immagini e video in cima alla pagina, il primo mostrato per primo.",
 "The credit note could not be made. Try again.": "Non è stato possibile creare la nota di credito. Riprova.",
 "The daily figures start after the first nightly count. Today’s numbers below are live.": "I dati giornalieri iniziano dopo il primo conteggio notturno. I numeri di oggi qui sotto sono in tempo reale.",
 "The date couldn't be read, so today's date is used.": "Non è stato possibile leggere la data, quindi si usa quella di oggi.",
 "The date shown on the post, in {zone}. Change it to backdate a post.": "La data mostrata sull'articolo, in {zone}. Cambiala per retrodatare un articolo.",
 "The day after a purchase, where to find it and how to get help.": "Il giorno dopo un acquisto: dove trovarlo e come ricevere aiuto.",
 "The day after someone starts a membership, show them what it includes.": "Il giorno dopo l'inizio di un abbonamento, mostra cosa include.",
 "The default tier": "Il livello predefinito",
 "The description could not be read.": "Impossibile leggere la descrizione.",
 "The description is too long. Shorten it, or remove formatting that came with a paste.": "La descrizione è troppo lunga. Accorciala o togli la formattazione arrivata con un incolla.",
 "The description is {size}, over the {limit} limit. Pictures saved inside the text by the old editor count toward it: remove them and add them again with the photo button.": "La descrizione è di {size}, oltre il limite di {limit}. Le immagini salvate nel testo dal vecchio editor contano: rimuovile e aggiungile di nuovo con il pulsante foto.",
 "The description is {size}, over the {limit} limit. Shorten it, or remove formatting that came with a paste.": "La descrizione è di {size}, oltre il limite di {limit}. Accorciala o rimuovi la formattazione arrivata con un incolla.",
 "The details on your payments account.": "I dati del tuo account di pagamento.",
 "The device and browser of the first page of each visit.": "Il dispositivo e il browser della prima pagina di ogni visita.",
 "The domain your emails come from once it is verified. Without one, they come from Storelib's address.": "Il dominio da cui partono le tue email una volta verificato. Senza, partono dall'indirizzo di Storelib.",
 "The draft has changes that are not published": "La bozza ha modifiche non pubblicate",
 "The draft is removed and nothing is sent.": "La bozza viene eliminata e non si invia nulla.",
 "The edit failed.": "La modifica non è riuscita.",
 "The editor is still loading your theme.": "L'editor sta ancora caricando il tema.",
 "The editor opens in your default language and currency. Switch them with your theme's own language and currency selectors on the page, as visitors do.": "L'editor si apre nella tua lingua e valuta predefinite. Cambiale con i selettori di lingua e valuta del tuo tema nella pagina, come fanno i visitatori.",
 "The editor, the preview and your website all open in your default language and your store currency. Switch them with your theme's own selectors on the page, as visitors do.": "L'editor, l'anteprima e il tuo sito si aprono nella lingua predefinita e nella valuta del negozio. Cambiale con i selettori del tuo tema nella pagina, come i visitatori.",
 "The email": "L'email",
