 "The newest exchange rates are from {asOf}, which is too old to use. Markets show your own prices until new rates arrive.": "I tassi di cambio più recenti sono del {asOf}, troppo vecchi per essere usati. I mercati mostrano i tuoi prezzi finché non arrivano quelli nuovi.",
