 "The order did not save.": "L'ordine non è stato salvato.",
 "The order goes to {name} by each variant's SKU, and its tracking comes back to your buyer by itself.": "L'ordine va a {name} tramite lo SKU di ogni variante e il tracciamento torna da solo all'acquirente.",
 "The order is gone": "L'ordine non esiste più",
