 "The order moves to the new address. Nothing is sent, as nothing in it has been paid for yet.": "L'ordine passa al nuovo indirizzo. Non si invia nulla, perché non è ancora stato pagato niente.",
 "The order pays the price of the last step it reaches. The first step starts from 0. A $0 step is free shipping from there.": "L'ordine paga il prezzo dell'ultima fascia raggiunta. La prima fascia parte da 0. Una fascia a 0 $ è spedizione gratuita da lì in poi.",
