 "These reports could not be loaded.": "Impossibile caricare questi report.",
 "These tags load on your page as well as your website.": "Questi tag si caricano sulla tua pagina e sul tuo sito.",
 "These will appear on your OnePage": "Compariranno sulla tua OnePage",
 "These words go to buyers in {language}, your website's language. Pick another language above to write its own.": "Questi testi vanno a chi compra in {language}, la lingua del tuo sito. Scegli un'altra lingua sopra per scrivere i suoi.",
 "They agreed to get my marketing emails. Add them to my email list.": "Ha accettato le mie email di marketing. Aggiungila alla mia lista.",
 "They are deleted for good, with their history. Live ones stop working at their addresses.": "Vengono eliminati per sempre, con la cronologia. Quelli online smettono di funzionare ai loro indirizzi.",
 "They are not on your email list. Marketing emails only go to people who subscribed.": "Questa persona non è nella tua lista. Le email di marketing vanno solo a chi si è iscritto.",
 "They are off for now. You can turn them on in": "Per ora sono disattivate. Puoi attivarle in",
 "They are real starter projects rather than presets, and they come after the editor. Start blank or with AI for now.": "Sono veri progetti di partenza, non preset, e arriveranno dopo l'editor. Per ora parti da zero o con l'IA.",
 "They are removed from your files, and anything that still shows one of them will show nothing.": "Vengono rimossi dai tuoi file e ciò che ne mostra ancora uno non mostrerà nulla.",
 "They are removed from your files. Any that a product, your website or anything else still uses stay there.": "Vengono rimossi dai tuoi file. Quelli che un prodotto, il tuo sito o altro usa ancora restano lì.",
 "They are unsubscribed and get no more of your emails.": "Viene disiscritto e non riceve più le tue email.",
 "They can ask again later.": "Potrà chiedere di nuovo più tardi.",
 "They can chat again": "Può di nuovo usare la chat",
 "They can open the community and post again, and keep their points, level and posts.{free}": "Può riaprire la community e pubblicare, mantenendo punti, livello e post.{free}",
 "They can read everything but cannot post, comment, react or chat until it ends.": "Può leggere tutto ma non pubblicare, commentare, reagire o chattare fino alla fine.",
 "They can't open your store any more.": "Non può più aprire il tuo negozio.",
 "They can't place an order until they click the link we email them when they sign up. Turns on sign in as well.": "Non possono ordinare finché non cliccano il link che inviamo alla registrazione. Attiva anche l'accesso.",
 "They get access again now, and keep their points, level and posts.{free}": "Ritrova subito l'accesso e mantiene punti, livello e post.{free}",
 "They get in without paying, and they are told what the ticket would have cost.": "Entrano senza pagare e vengono informati di quanto sarebbe costato il biglietto.",
 "They get this tier without paying, until you end it.": "Ottiene questo livello senza pagare finché non lo termini.",
 "They group the shelf for members, like Templates or Recordings. Taking one out keeps its items.": "Raggruppano lo scaffale per i membri, come Modelli o Registrazioni. Toglierne una conserva i suoi elementi.",
 "They have {points} now. ": "Ora ne ha {points}. ",
 "They hold the stock and ship it.": "Tiene la merce e la spedisce.",
 "They join as {role}: {value}. They sign in with their own Storelib account.": "Entra come {role}: {value}. Accede con il proprio account Storelib.",
 "They lose access and cannot join again unless you unban them.": "Perde l'accesso e non può iscriversi di nuovo, a meno che non rimuovi il ban.",
 "They lose access at once. You can let them back in from Not active.": "Perdono subito l'accesso. Puoi farli rientrare da Non attivo.",
 "They lose access now and can join again. A paid membership keeps billing until they cancel it.": "Perde l'accesso ora e può iscriversi di nuovo. Un abbonamento a pagamento continua a essere addebitato finché non lo annulla.",
 "They lose access until you bring them back. Their posts stay.": "Perde l'accesso finché non lo riporti. I suoi post restano.",
 "They need a database update (SQL part 283) before they can be used.": "Richiedono un aggiornamento del database (parte SQL 283) prima di poter essere usate.",
 "They need the Forms database update (SQL parts 372 and 375 in Admin › SQL updates). Everything else keeps working.": "Serve l'aggiornamento del database dei Moduli (parti SQL 372 e 375 in Admin › Aggiornamenti SQL). Tutto il resto continua a funzionare.",
 "They pay in a window on your page, like joining a community. For downloads and courses.": "Pagano in una finestra sulla tua pagina, come quando si entra in una community. Per download e corsi.",
 "They pick a reason from your list and the items. You get an email and approve or decline it from the order.": "Sceglie un motivo dal tuo elenco e gli articoli. Ricevi un'email e approvi o rifiuti dall'ordine.",
 "They see it, choose options, then check out": "Lo vedono, scelgono le opzioni, poi pagano",
