 "To count stock, have it fulfilled from one of your own locations.": "Per contare la merce, fallo evadere da una delle tue sedi.",
 "To days": "A (giorni)",
 "To do": "Da fare",
 "To do ({count})": "Da fare ({count})",
 "To hand it over in person, turn on local pickup in Settings › Shipping.": "Per consegnarlo di persona, attiva il ritiro in sede in Impostazioni › Spedizioni.",
 "To keep your payouts going, Stripe asks for this now{value}. It takes a minute.": "Per continuare a ricevere i bonifici, Stripe lo chiede ora{value}. Ci vuole un minuto.",
 "To make one link stand out, use the sparkle button on that link in Links.": "Per far risaltare un link, usa il pulsante scintille su quel link in Link.",
 "To move a photo or video, press Space or Enter on it, then the arrow keys. Press Space or Enter again to drop it, or Escape to put it back. The first is the thumbnail.": "Per spostare una foto o un video, premi Spazio o Invio sopra, poi le frecce. Premi di nuovo Spazio o Invio per rilasciarlo, o Esc per rimetterlo a posto. Il primo è la miniatura.",
 "To move a picture or video, press Space or Enter on it, then the arrow keys. Press Space or Enter again to drop it, or Escape to put it back. The first is shown first.": "Per spostare un'immagine o un video, premi Spazio o Invio su di esso, poi le frecce. Premi di nuovo Spazio o Invio per lasciarlo, o Esc per rimetterlo al suo posto. Il primo viene mostrato per primo.",
 "To move a question, press Space or Enter on its handle, then the up and down arrow keys. Press Space or Enter again to drop it, or Escape to put it back.": "Per spostare una domanda, premi Spazio o Invio sulla maniglia, poi le frecce su e giù. Premi di nuovo Spazio o Invio per rilasciarla, o Esc per rimetterla a posto.",
 "To move a space, press Enter on its handle, then the arrow keys. Press Enter again to drop it, or Escape to put it back.": "Per spostare uno spazio, premi Invio sulla sua maniglia, poi le frecce. Premi di nuovo Invio per lasciarlo, o Esc per rimetterlo al suo posto.",
 "To move an item, press Enter on its handle, then the arrow keys. Press Enter again to drop it, or Escape to put it back.": "Per spostare un elemento, premi Invio sulla sua maniglia, poi le frecce. Premi di nuovo Invio per rilasciarlo, o Esc per rimetterlo a posto.",
 "To move an option, press Space on its handle, then the up and down arrow keys, then Space again.": "Per spostare un'opzione, premi Spazio sulla maniglia, poi le frecce su e giù, poi di nuovo Spazio.",
 "To send a product here: in the product, choose Print on demand and the {value} location, and give each variant the same SKU it has in {name}.": "Per inviare un prodotto qui: nel prodotto, scegli Stampa su richiesta e la sede {value}, e dai a ogni variante lo stesso SKU che ha in {name}.",
 "To send a product here: in the product, choose {value} and the {value2} location, then match each variant to {name}'s below.": "Per inviare un prodotto qui: nel prodotto, scegli {value} e la sede {value2}, poi abbina ogni variante a quelle di {name} qui sotto.",
