 "Visit the studio": "Visita lo studio",
 "Visit {brand}'s website on Storelib": "Visita il sito di {brand} su Storelib",
 "Visitor currencies": "Valute per i visitatori",
 "Visitor speed is not set up yet": "La velocità per i visitatori non è ancora configurata",
 "Visitor's name": "Nome del visitatore",
 "Visitors": "Visitatori",
 "Visitors are matched by the country they browse from, and can change it with the currency or country selector. Their choice is remembered.": "I visitatori sono abbinati in base al paese da cui navigano e possono cambiarlo con il selettore di valuta o paese. La scelta viene ricordata.",
 "Visitors are matched by the country they browse from, and can change it with the currency selector. Their choice is remembered.": "I visitatori vengono abbinati al paese da cui navigano e possono cambiarlo con il selettore di valuta. La loro scelta viene ricordata.",
 "Visitors by country": "Visitatori per paese",
 "Visitors by the system of their device, with its share of all visitors. Read from the browser's signature, and from its platform hint where the signature is vague.": "Visitatori per sistema del dispositivo, con la quota sul totale. Letto dalla firma del browser, e dal suo indizio di piattaforma quando la firma è vaga.",
 "Visitors confirm before it opens": "I visitatori confermano prima dell'apertura",
 "Visitors get this link only after their response is saved. It never appears in the page.": "I visitatori ricevono questo link solo dopo che la risposta è stata salvata. Non compare mai nella pagina.",
 "Visitors go to {goesTo} for 30 days, then it stops.": "I visitatori vanno su {goesTo} per 30 giorni, poi si interrompe.",
 "Visitors in the EU, the UK and Switzerland are counted in full once they accept cookies; before that Google gets a cookieless ping.": "I visitatori di UE, Regno Unito e Svizzera vengono contati del tutto quando accettano i cookie; prima, Google riceve un ping senza cookie.",
 "Visitors may see a different order depending on their location or preferences.": "I visitatori potrebbero vedere un ordine diverso in base a posizione o preferenze.",
 "Visitors open the course page, where they can buy it.": "I visitatori aprono la pagina del corso, dove possono comprarlo.",
 "Visitors open your website in your default language and store currency, and switch with your theme's own selectors.": "I visitatori aprono il tuo sito nella lingua predefinita e nella valuta del negozio, e cambiano con i selettori del tuo tema.",
 "Visitors pick a time before answering. For Calendly or another booking page, use a button action instead.": "I visitatori scelgono un orario prima di rispondere. Per Calendly o un'altra pagina di prenotazione, usa un'azione del pulsante.",
 "Visitors reach your website at your own address.": "I visitatori raggiungono il tuo sito al tuo indirizzo.",
 "Visitors see a placeholder until you publish again.": "I visitatori vedono una pagina provvisoria finché non pubblichi di nuovo.",
 "Visitors see a placeholder. {name} was the last one live.": "I visitatori vedono una pagina provvisoria. {name} è stato l'ultimo online.",
 "Visitors see it once {title} is published in Products › Collections.": "I visitatori la vedranno quando {title} sarà pubblicata in Prodotti › Collezioni.",
 "Visitors see the community at this domain. Members sign in on {main}.": "I visitatori vedono la community su questo dominio. I membri accedono su {main}.",
 "Visitors see the last version you published.": "I visitatori vedono l'ultima versione pubblicata.",
 "Visitors see this once {name} is published and public.": "I visitatori la vedranno quando {name} sarà pubblicata e pubblica.",
 "Visitors see your password page until they type the password.": "I visitatori vedono la pagina della password finché non la inseriscono.",
 "Visitors start in": "I visitatori iniziano in",
 "Visitors switch with the language selector. On a Storelib theme it sits under the footer by itself. On a theme you imported from Shopify it is the theme's own selector, turned on in the editor (Show language, usually in the header or footer).": "I visitatori cambiano con il selettore di lingua. In un tema Storelib sta da solo sotto il piè di pagina. In un tema importato da Shopify è il selettore del tema, attivato nell'editor (Show language, di solito nell'intestazione o nel piè di pagina).",
 "Visitors switch with your theme's language selector. Turn on Show visitors their own language to open a first visit in their browser's language.": "I visitatori cambiano con il selettore di lingua del tuo tema. Attiva Mostra ai visitatori la loro lingua per aprire la prima visita nella lingua del browser.",
 "Visitors who turn off motion on their device see the site without it.": "Chi disattiva il movimento sul dispositivo vede il sito senza.",
 "Visitors: where visits came from, from their connection. Orders: where buyers are, from the order, with their revenue.": "Visitatori: da dove arrivano le visite, in base alla connessione. Ordini: dove sono gli acquirenti, dall'ordine, con i loro ricavi.",
 "Visits": "Visite",
 "Visits by source": "Visite per fonte",
 "Visits older than three days are counted by day, not by hour.": "Le visite di oltre tre giorni fa sono contate per giorno, non per ora.",
 "Visits to your pages, by day.": "Visite alle tue pagine, per giorno.",
 "Visits to your pages. A visit ends after 30 minutes without a page.": "Visite alle tue pagine. Una visita termina dopo 30 minuti senza pagine.",
 "Visual stability": "Stabilità visiva",
 "Voice input cannot hear this language here. Type it instead.": "L'input vocale non capisce questa lingua qui. Scrivilo.",
 "Voice input needs a connection. Check it and try again.": "L'input vocale richiede una connessione. Controllala e riprova.",
 "Voice input stopped before it heard anything. Try again, or type it.": "L'input vocale si è fermato prima di sentire qualcosa. Riprova o scrivilo.",
 "Void label": "Annulla etichetta",
 "Void this {providerName} label? {cost} is refunded once the carrier agrees it wasn't used, and the items go back to unfulfilled.": "Annullare questa etichetta {providerName}? {cost} viene rimborsato quando il corriere conferma che non è stata usata, e gli articoli tornano non evasi.",
