 "We write in a warm, plain voice. Never use gradients.": "Scriviamo con un tono caldo e semplice. Mai usare sfumature.",
 "We'll build your OnePage around this": "Costruiremo la tua OnePage intorno a questo",
 "We'll send a verification code to": "Invieremo un codice di verifica a",
