 "What you price in. Visitors anywhere not listed under More currencies see prices in it and pay in it.": "La valuta dei tuoi prezzi. I visitatori ovunque non sia elencato in Altre valute vedono i prezzi in questa valuta e pagano in questa valuta.",
 "What you price in. Visitors in {country}, and anywhere not listed under More currencies, see prices in it and pay in it.": "La valuta dei tuoi prezzi. I visitatori in {country}, e ovunque non sia elencato in Altre valute, vedono i prezzi in questa valuta e pagano in questa valuta.",
