 "What you wrote in this email is replaced.": "Ciò che hai scritto in questa email viene sostituito.",
 "What your buyers and members get from you, and when: digital products, physical products and communities, each apart. Open one to see it as it is sent and change its words. A reply comes to your contact email.": "Cosa ricevono da te i tuoi acquirenti e membri, e quando: prodotti digitali, prodotti fisici e community, ognuno a parte. Aprine una per vederla come viene inviata e cambiarne le parole. Una risposta arriva alla tua email di contatto.",
 "What your buyers get from you, and when. Open one to see it and change its words. Each goes out with your store's name, and a reply comes to your contact email.": "Cosa ricevono gli acquirenti da te, e quando. Aprine una per vederla e modificarne il testo. Ognuna parte con il nome del negozio e le risposte arrivano alla tua email di contatto.",
