 "When a paid membership is cancelled": "Quando un abbonamento a pagamento viene annullato",
 "When a paid membership starts": "Quando inizia un abbonamento a pagamento",
 "When a review comes in": "Quando arriva una recensione",
 "When a shipment is marked as failed: the carrier, or your own delivery, couldn't deliver it.": "Quando una spedizione è segnata come non riuscita: il corriere, o la tua consegna, non è riuscito a consegnarla.",
 "When a store's owner invites you, it shows here and you can open it from your own account.": "Quando il proprietario di un negozio ti invita, compare qui e puoi aprirlo dal tuo account.",
 "When a ticket is refunded.": "Quando un biglietto viene rimborsato.",
 "When buyers can come. Shown at checkout and in the pickup email.": "Quando possono venire gli acquirenti. Mostrato al checkout e nell'email di ritiro.",
 "When does Pro pay for itself?": "Quando Pro si ripaga?",
 "When it is sent": "Quando viene inviato",
 "When it pushes to": "Quando fa push su",
 "When it pushes to {branch}, the change shows here as a draft within seconds.": "Quando fa push su {branch}, la modifica compare qui come bozza in pochi secondi.",
 "When it's marked delivered.": "Quando viene segnato come consegnato.",
 "When members leave they can say why. Their answers show up here.": "Quando i membri se ne vanno possono dire perché. Le risposte compaiono qui.",
 "When members report a post, a comment or somebody, it lands here.": "Quando i membri segnalano un post, un commento o qualcuno, arriva qui.",
 "When memberships end": "Quando terminano le iscrizioni",
 "When pressed": "Quando premuto",
 "When returns are on, a buyer sees Request a return on their order page for as many days as your return window.": "Con i resi attivi, l'acquirente vede Richiedi un reso nella pagina dell'ordine per tutti i giorni del periodo di reso.",
 "When review emails go, and what they say, is under Requests.": "Quando partono le email di recensione, e cosa dicono, si trova in Richieste.",
 "When somebody asks to join, they show here with their answers.": "Quando qualcuno chiede di unirsi, compare qui con le sue risposte.",
 "When somebody writes to you through the contact form on your website, the message shows here and in your email.": "Quando qualcuno ti scrive dal modulo di contatto del tuo sito, il messaggio compare qui e nella tua email.",
 "When someone buys a ticket to a paid event, with the calendar file.": "Quando qualcuno compra un biglietto per un evento a pagamento, con il file del calendario.",
 "When someone joins": "Quando qualcuno si iscrive",
 "When someone joins a membership you sell on its own, with what they pay and when.": "Quando qualcuno si iscrive a un abbonamento che vendi da solo, con quanto paga e quando.",
 "When someone joins a paid plan, with what they pay and when.": "Quando qualcuno si iscrive a un piano a pagamento, con quanto paga e quando.",
 "When someone joins your list": "Quando qualcuno si iscrive alla tua lista",
