 "When you mark a pickup order ready.": "Quando segni pronto un ordine con ritiro.",
 "When you mark it collected.": "Quando lo segni come ritirato.",
 "When you mark items shipped, with the tracking.": "Quando segni gli articoli come spediti, con il tracciamento.",
 "When you post an announcement": "Quando pubblichi un annuncio",
 "When you publish changes, new and edited text is translated into your other languages within a few minutes. Translations you edit yourself are never replaced.": "Quando pubblichi modifiche, il testo nuovo e modificato viene tradotto nelle altre lingue in pochi minuti. Le traduzioni che modifichi tu non vengono mai sostituite.",
 "When you published": "Quando hai pubblicato",
 "When you refund a download, course or membership, here or in Stripe. Its download stops working.": "Quando rimborsi un download, un corso o un abbonamento, qui o in Stripe. Il suo download smette di funzionare.",
 "When you refund all or part of an order, here or in Stripe.": "Quando rimborsi tutto o parte di un ordine, qui o in Stripe.",
 "When you write one. It goes to members who keep community emails on, one a day at most.": "Quando ne scrivi una. Va ai membri che tengono attive le email della community, al massimo una al giorno.",
 "Where": "Dove",
