 "Where each order was placed: your online store, Storelib (Explore, product and creator pages, communities), your OnePage or a checkout link.": "Dove è stato effettuato ogni ordine: il tuo negozio online, Storelib (Explore, pagine prodotto e creator, community), la tua OnePage o un link di pagamento.",
 "Where each visit came from, judged by its first page: a search engine, a social app, an email, another website, or typed in directly.": "Da dove è arrivata ogni visita, in base alla prima pagina: un motore di ricerca, un social, un'email, un altro sito o digitata direttamente.",
