 "Will be {wanted}{suffix}. Your username stays the same.": "Sarà {wanted}{suffix}. Il tuo username resta uguale.",
 "Will reconnect automatically when you’re back online.": "Si riconnetterà automaticamente quando tornerai online.",
 "Wins": "Successi",
 "With Show visitors their own language on, a first visit opens in the published language the browser asks for, once. A close match, or only the country to go by, gets a small offer on the page instead. A market can also start its countries in its own language. After that the visitor's choice wins, and search engines still see every language at its own address.": "Con “Mostra ai visitatori la loro lingua” attivo, una prima visita si apre una volta nella lingua pubblicata che chiede il browser. Una lingua simile, o solo il paese, riceve invece un piccolo suggerimento sulla pagina. Un mercato può anche aprire i suoi paesi nella propria lingua. Poi vale la scelta del visitatore, e i motori di ricerca vedono ancora ogni lingua al proprio indirizzo.",
 "With Storelib": "Con Storelib",
 "With Storelib's own tracking, nothing to set up.": "Con il tracciamento di Storelib, niente da configurare.",
