 "You are on Free now.": "Ora sei su Free.",
 "You are on Pro now": "Ora sei su Pro",
 "You are on an earlier Pro plan at {amount} a month, with a fee of": "Hai un piano Pro precedente a {amount} al mese, con una commissione del",
 "You are still signed in and nothing you saved is lost.": "Hai ancora effettuato l'accesso e nulla di ciò che hai salvato è andato perso.",
 "You are the seller of your products, so registering for tax where you need to, and filing and paying it, stays with you. Storelib does not file or pay tax for you.": "Sei tu il venditore dei tuoi prodotti, quindi la registrazione fiscale dove serve, la dichiarazione e il pagamento restano a te. Storelib non dichiara né paga imposte per te.",
 "You are the seller, so registering for tax where you need to, filing returns and paying the tax stay with you. Storelib does not file or pay tax for you.": "Sei tu il venditore: registrarti dove serve, presentare le dichiarazioni e versare l'imposta restano a te. Storelib non dichiara né versa imposte per te.",
 "You are {value} here": "Qui sei {value}",
 "You bring orders to buyers nearby, by postal code. Offered at checkout next to shipping.": "Consegni gli ordini agli acquirenti vicini, per CAP. Offerto al checkout accanto alla spedizione.",
 "You can add products to it later in Products › Collections.": "Puoi aggiungere prodotti più tardi in Prodotti › Collezioni.",
