 "You deliver this one yourself. Mark it delivered when it's handed over.": "Questo lo consegni tu. Segnalo come consegnato quando lo dai.",
 "You did not meet the federal threshold ($20,000 + 200 transactions). This draft summary is for your records. Ask a tax professional for filing guidance.": "Non hai raggiunto la soglia federale (20.000 $ e 200 transazioni). Questo riepilogo in bozza è per i tuoi archivi. Chiedi a un commercialista come dichiararlo.",
 "You didn't meet the threshold. Download a draft summary for your tax professional.": "Non hai raggiunto la soglia. Scarica un riepilogo in bozza per il tuo commercialista.",
